"""Portable reverse transition regression; no Blender import or native fixtures."""
import ast,json,os,types,unittest
from pathlib import Path
ROOT=Path(os.environ['DATARAIDERS_TEST_REPOSITORY']) if os.environ.get('DATARAIDERS_TEST_REPOSITORY') else next(p for p in Path(__file__).resolve().parents if (p/'Shared/materials/native/native_families.py').is_file())
SOURCE=Path(os.environ.get('DATARAIDERS_TRANSITION_STAGE',ROOT))
class NativeTransition(unittest.TestCase):
    def helper(self):
        tree=ast.parse((SOURCE/'Shared/materials/native/native_families.py').read_text(encoding='utf-8'));function=next(n for n in tree.body if isinstance(n,ast.FunctionDef) and n.name=='clear_character_fallback_provenance');namespace={'json':json};exec(compile(ast.Module(body=[function],type_ignores=[]),'<actual metadata helper>','exec'),namespace);return namespace[function.name]
    def test_fallback_to_native_clears_status_but_keeps_override_controls(self):
        material={'dr_character_fallback':'teeth','dr_character_fallback_revision':'original-character-v2','dr_character_missing_source':'missing old','dr_character_fallback_note':'old approximation','arc_teeth_setup':'fallback-static-v2','arc_face_surface_setup':'fallback-principled-v2','arc_build_report':json.dumps({'status':'original-character-fallback','diagnostics':['old missing'],'user_override':{'color':'explicitred'}}),'dr_native_route_diagnostic':'Original character fallback active: old missing','dr_native_user_override':True,'arc_native_user_override':True,'arc_user_roughness':.217}
        self.helper()(material)
        self.assertFalse(any(key.startswith('dr_character_') for key in material));self.assertNotIn('arc_teeth_setup',material);self.assertNotIn('arc_face_surface_setup',material);self.assertNotIn('dr_native_route_diagnostic',material);self.assertEqual(json.loads(material['arc_build_report']),{'user_override':{'color':'explicitred'}});self.assertTrue(material['dr_native_user_override']);self.assertTrue(material['arc_native_user_override']);self.assertEqual(material['arc_user_roughness'],.217)
    def test_no_override_old_fallback_report_removed_native_proof_untouched(self):
        material={'arc_build_report':json.dumps({'status':'original-character-fallback'}),'dr_native_family':'teeth','dr_native_report':'new currentnativeproof','arc_teeth_setup':'native-teeth-v1'};self.helper()(material);self.assertNotIn('arc_build_report',material);self.assertEqual(material['dr_native_report'],'new currentnativeproof');self.assertEqual(material['arc_teeth_setup'],'native-teeth-v1')
    def test_existing_fallback_contributes_only_numeric_sss_source(self):
        source=ast.parse((SOURCE/'Shared/materials/character.py').read_text(encoding='utf-8'));function=next(n for n in source.body if isinstance(n,ast.FunctionDef) and n.name=='_setup_head_slot_head');guard=next(n for n in ast.walk(function) if isinstance(n,ast.If) and "mat.get('dr_character_fallback') == 'head'" in ast.unparse(n.test))
        class Mat(dict):pass
        material=Mat(dr_character_fallback='head');material.node_tree=object();namespace={'mat':material,'previous_face':None};exec(compile(ast.Module(body=[guard],type_ignores=[]),'<actual fallback SSS source guard>','exec'),namespace);self.assertIs(namespace['previous_face'],material.node_tree)
        existing=object();namespace={'mat':material,'previous_face':existing};exec(compile(ast.Module(body=[guard],type_ignores=[]),'<actual existing native source>','exec'),namespace);self.assertIs(namespace['previous_face'],existing)
    def test_native_cleanup_is_after_compile_success_and_inside_face_success(self):
        source=ast.parse((SOURCE/'Shared/materials/native/native_families.py').read_text(encoding='utf-8'));setup=next(n for n in source.body if isinstance(n,ast.FunctionDef) and n.name=='setup');calls=[n for n in setup.body if isinstance(n,ast.Expr) and isinstance(n.value,ast.Call)];names=[n.value.func.id for n in calls if isinstance(n.value.func,ast.Name)];self.assertLess(names.index('compile_plan'),names.index('clear_character_fallback_provenance'))
        source=ast.parse((SOURCE/'Shared/materials/character.py').read_text(encoding='utf-8'));setup=next(n for n in source.body if isinstance(n,ast.FunctionDef) and n.name=='_setup_head_slot_head');clean=next(n for n in ast.walk(setup) if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='clear_character_fallback_provenance');self.assertGreater(clean.lineno,next(n.lineno for n in ast.walk(setup) if isinstance(n,ast.If) and ast.unparse(n.test)=='albedo is not None and albedo.links'))
if __name__=='__main__':unittest.main(verbosity=2)
